// Starting a trial with a farm already in it.
//
// Somebody evaluating this has about three minutes of patience, and an empty
// app answers none of the questions they came with. So a new account can start
// with a complete invented season — paddocks, silos with grain in them,
// contracts part delivered, a fert report with something to report — and
// delete it once they have seen enough.
//
// The data lives in docs/demo/seed.json, generated by tools/make-demo-seed.mjs
// and checked by tests/demo.test.mjs. Its ids are deliberately not UUIDs, so
// remapIds() reissues every one on import and two trial accounts never collide
// on a primary key.

import { DEFAULT_BUSINESS_DETAILS, prepareImport, newId } from './import.js?v=380';
import { APP_VERSION } from './version.js?v=380';

const WANTED_KEY = 'grainflow.seedSample';

/** Remember, across the sign-up round trip, that they asked for sample data. */
export function wantSampleData() {
  try { sessionStorage.setItem(WANTED_KEY, '1'); } catch { /* private mode */ }
}

/**
 * Did they? Answering also forgets, because this must happen exactly once —
 * a flag left set would re-import the sample farm over the top of their real
 * work on the next sign-in.
 */
export function takeSampleDataRequest() {
  try {
    const wanted = sessionStorage.getItem(WANTED_KEY) === '1';
    sessionStorage.removeItem(WANTED_KEY);
    return wanted;
  } catch { return false; }
}

/**
 * The sample season, carrying the name they actually chose.
 *
 * The seed file has business details of its own — Kurrajong Downs Pty Ltd —
 * and importing it verbatim would push that straight over the farm name the
 * person typed thirty seconds earlier, because businessDetails.entityName is
 * what maps to farms.entity_name. They would name their farm and watch it
 * become somebody else's.
 *
 * So the sample's identity is dropped and theirs put in its place. Everything
 * else about the business details starts empty, which is also the honest
 * answer: those are the fields they need to fill in with their own, and a
 * plausible-looking ABN sitting there invites them not to.
 */
export function sampleStateFor(rawJson, farmName) {
  const state = JSON.parse(rawJson);
  const name = String(farmName || '').trim();
  state.businessDetails = {
    ...DEFAULT_BUSINESS_DETAILS,
    farmName: name,
    entityName: name,
    paymentTermsDays: 30,
  };
  return state;
}

/**
 * Is this a sample farm whose owner may refresh it to the latest sample? The owner only, because it replaces everything on the
 * farm. The sample is copied once when a farm is made, so a farm made earlier keeps the old silos, contracts and terms until it is.
 */
export const sampleRefreshOffered = (currentYear = '', role = 'owner') => /^sample/i.test(currentYear || '') && role === 'owner';

/** The earlier seasons the sample farm carries. */
export const SAMPLE_HISTORY = ['Sample 2024', 'Sample 2025'];

/** Is this the sample farm, and still missing some of its earlier seasons? Offered to the owner and manager only. */
export function sampleHistoryOffered(years = [], currentYear = '', role = 'owner') {
  return /^sample/i.test(currentYear || '') && ['owner', 'manager'].includes(role)
    && SAMPLE_HISTORY.some((l) => !years.includes(l));
}

/**
 * The sample farm's earlier seasons, ready to add to a sample farm that was set up before it had any.
 *
 * Every id is reissued on the way through, as for a new trial, so two farms never share a primary key. Nothing of the
 * sample's business details comes with them, and the season in use is not among them: only the earlier ones, and only
 * those the farm does not already have.
 * @param {object} seed   the parsed seed file
 * @param {string[]} have the season labels the farm has now
 * @returns {Record<string, object>} label -> season, in the shape db.addSampleSeasons() stores
 */
export function sampleHistoryFrom(seed, have = []) {
  const wanted = SAMPLE_HISTORY.filter((l) => seed?.years?.[l] && !have.includes(l));
  if (!wanted.length) return {};
  const { state } = prepareImport({
    version: seed.version ?? 2,
    currentYear: wanted[0],
    years: Object.fromEntries(wanted.map((l) => [l, seed.years[l]])),
  });
  const out = {};
  for (const label of wanted) {
    const y = state.years[label];
    out[label] = {
      // the sections a season carries that the seed leaves out, as addPastSeason gives a season of its own
      payables: [], orders: [], freightOrders: [], inputStock: [], sprayJobs: [],
      ...y,
      fields: (y.fields || []).map((f) => ({
        ...f,
        ...(f.boundary ? { __hasBoundary: true } : {}),
        ...(f.property ? { __hasProperty: true } : {}),
      })),
    };
  }
  return out;
}

/**
 * Is this the sample farm, with the sample contract that carries the sample orders, and with no grain orders or freight
 * orders yet? Offered to the owner and manager only. A farm made before the sample had orders is the one that gets it.
 */
export function sampleOrdersOffered(sales = [], orders = [], freightOrders = [], currentYear = '', role = 'owner') {
  return /^sample/i.test(currentYear || '') && ['owner', 'manager'].includes(role)
    && !orders.length && !freightOrders.length && sales.some((s) => s.contractNo === SAMPLE_ORDER_CONTRACT);
}

/** The contract the sample's grain order and freight order are against. */
export const SAMPLE_ORDER_CONTRACT = 'RGT-4471';

/**
 * The sample grain order and the freight order that carts it, ready to add to a sample farm made before it had any:
 * linked to that farm's own copy of the contract, with ids of their own so no two farms share one.
 * @param {object} seed   the parsed seed file
 * @param {object[]} sales the farm's contracts now
 * @returns {{order: object, freightOrder: object}|null} null when the seed has none, or the farm has no such contract
 */
export function sampleOrdersFrom(seed, sales = []) {
  const y = seed?.years?.[seed.currentYear] || Object.values(seed?.years || {})[0];
  const order = y?.orders?.[0];
  const freight = y?.freightOrders?.[0];
  const sale = sales.find((s) => s.contractNo === SAMPLE_ORDER_CONTRACT);
  if (!order || !freight || !sale) return null;
  const orderId = newId();
  return {
    order: { ...order, id: orderId, saleId: sale.id },
    freightOrder: { ...freight, id: newId(), saleId: sale.id, orderId },
  };
}

/** Fetch the seed. Versioned so a device cannot be served last release's. */
export async function fetchSampleFarm(farmName) {
  const res = await fetch(`./demo/seed.json?v=${APP_VERSION}`, { cache: 'no-cache' });
  if (!res.ok) throw new Error(`sample data unavailable (${res.status})`);
  return sampleStateFor(await res.text(), farmName);
}

// ---------------------------------------------------------------------------
// Cotton and hay for a sample farm that was made before the sample grew any.
// ---------------------------------------------------------------------------

/** The commodities the cotton and hay part of the sample is built on. */
const COTTON_HAY_NAMES = ['Cotton', 'Lucerne hay', 'Wheat straw'];
const COTTON_HAY_IDS = ['cotton', 'cottonseed', 'lucerne', 'wheatstraw'];

/** The contract and paddock the sample's cotton is made of: a farm that has them already has had it added. */
export const SAMPLE_COTTON_CONTRACT = 'WCM-2610';
export const SAMPLE_COTTON_PADDOCK = 'Cotton North';

/**
 * Is this the sample farm, without the sample's cotton and hay yet? Offered to the owner and manager only. A farm that has its
 * own Cotton or hay commodity is still offered it: those are used, not doubled.
 */
export function sampleCottonHayOffered(sales = [], fields = [], currentYear = '', role = 'owner') {
  return /^sample/i.test(currentYear || '') && ['owner', 'manager'].includes(role)
    && !sales.some((s) => s.contractNo === SAMPLE_COTTON_CONTRACT) && !fields.some((f) => f.name === SAMPLE_COTTON_PADDOCK);
}

/**
 * The sample's cotton and hay, ready to add to a sample farm made before it had any: the three commodities, the cotton and
 * lucerne paddocks, the gin yard, bale shed and hay sheds, the cotton and hay contracts, their loads (modules, the ginning
 * run, bales of hay), the two invoices, and, if the farm has none, the bills, inputs and spray request that come with the
 * sample. Every id is reissued, as for a new trial. The straw baled off wheat paddocks goes onto the farm's own paddocks of
 * the same name, and a load from a paddock the farm does not have is left out.
 * @param {object} seed the parsed seed file
 * @param {{commodities?: object[], fields?: object[], payables?: object[], inputStock?: object[], sprayJobs?: object[]}} farm what the farm has now. A commodity it has by the same name is used, not added again.
 * @returns {object|null} null when the seed carries no cotton or hay
 */
export function sampleCottonHayFrom(seed, farm = {}) {
  const y = seed?.years?.[seed.currentYear] || Object.values(seed?.years || {})[0];
  if (!y || !COTTON_HAY_IDS.every((id) => (y.commodities || []).some((c) => c.id === id))) return null;
  const isOurs = (id) => COTTON_HAY_IDS.includes(id);
  const own = {
    commodities: y.commodities.filter((c) => isOurs(c.id)),
    fields: y.fields.filter((f) => isOurs(f.commodityId)),
    storages: y.storages.filter((s) => isOurs(s.commodityId)),
    sales: y.sales.filter((s) => isOurs(s.commodityId)),
    movements: y.movements.filter((m) => isOurs(m.commodityId)).sort((a, b) => a.ticketNo - b.ticketNo),
  };
  const ids = new Map();
  const haveByName = new Map((farm.commodities || []).map((c) => [String(c.name).toLowerCase(), c.id]));
  const added = [];
  for (const c of own.commodities) {
    const mine = haveByName.get(String(c.name).toLowerCase());
    if (mine) ids.set(c.id, mine); else { ids.set(c.id, newId()); added.push(c); }
  }
  for (const k of ['fields', 'storages', 'sales', 'movements']) for (const r of own[k]) ids.set(r.id, newId());
  // the gin's bill, which the lint buyer pays: it belongs with the ginning run, so it comes whatever bills the farm already has
  const ginBills = (y.payables || []).filter((p) => p.payer === 'buyer');
  const ginBillIds = new Map(ginBills.map((p) => [p.id, newId()]));
  // the seed's wheat paddocks, matched to the farm's by name
  const farmFieldByName = new Map((farm.fields || []).map((f) => [String(f.name).toLowerCase(), f.id]));
  const seedFieldName = new Map(y.fields.map((f) => [f.id, String(f.name).toLowerCase()]));
  const outside = (oldId) => farmFieldByName.get(seedFieldName.get(oldId)) || null;
  const ref = (oldId) => (ids.has(oldId) ? ids.get(oldId) : null);
  const refTyped = (v) => {
    const i = typeof v === 'string' ? v.indexOf(':') : -1;
    if (i < 0) return v;
    const r = ref(v.slice(i + 1));
    return r ? `${v.slice(0, i)}:${r}` : '';
  };

  const commodities = added.map((c) => ({ ...c, id: ids.get(c.id) }));
  const fields = own.fields.map((f) => ({
    ...f, id: ids.get(f.id), commodityId: ref(f.commodityId),
    ...(f.boundary ? { __hasBoundary: true } : {}), ...(f.property ? { __hasProperty: true } : {}),
    ...((f.modulesPicked || []).length ? { __hasModulesPicked: true } : {}), ...((f.balesBaled || []).length ? { __hasBalesBaled: true } : {}),
  }));
  const strawBaled = y.fields.filter((f) => !isOurs(f.commodityId) && (f.balesBaled || []).length)
    .map((f) => ({ fieldId: outside(f.id), baled: f.balesBaled.map((b) => ({ ...b, ...(b.commodityId ? { commodityId: ref(b.commodityId) } : {}) })) }))
    .filter((s) => s.fieldId);
  const storages = own.storages.map((s) => ({ ...s, id: ids.get(s.id), commodityId: ref(s.commodityId) }));
  const sales = own.sales.map((s) => ({ ...s, id: ids.get(s.id), commodityId: ref(s.commodityId) }));

  const legOf = (leg) => {
    if (ids.has(leg.id)) return { ...leg, id: ids.get(leg.id) };
    if (leg.type === 'field' && outside(leg.id)) return { ...leg, id: outside(leg.id) };
    return null;
  };
  const movements = [];
  for (const m of own.movements) {
    const froms = (m.froms || []).map(legOf);
    const tos = (m.tos || []).map(legOf);
    if (froms.includes(null) || tos.includes(null)) continue;   // a load from a paddock this farm does not have
    movements.push({
      ...m, id: ids.get(m.id), commodityId: ref(m.commodityId), froms, tos,
      ...(m.gin ? { gin: { ...m.gin, allocations: (m.gin.allocations || []).map((a) => ({ ...a, to: refTyped(a.to) })), ...(m.gin.seedTo ? { seedTo: refTyped(m.gin.seedTo) } : {}), ...(m.gin.payableId ? { payableId: ginBillIds.get(m.gin.payableId) || '' } : {}), ...(m.gin.ginContract ? { ginContract: ref(m.gin.ginContract) } : {}) } } : {}),
    });
  }
  const kept = new Set(movements.map((m) => m.id));
  const invoices = (y.invoices || []).filter((i) => ids.has(i.saleId)).sort((a, b) => a.invoiceNo - b.invoiceNo).map((i) => ({
    ...i, id: newId(), saleId: ref(i.saleId),
    lines: (i.lines || []).map((l) => ({
      ...l, ...(l.movementId ? { movementId: kept.has(ref(l.movementId)) ? ref(l.movementId) : null } : {}),
      ...(l.ginRunId ? { ginRunId: ref(l.ginRunId) } : {}),
    })),
  }));

  // bills, inputs and the spray request: only for a farm that has none, and with no link to a contract or silo it may not have
  const none = (k) => !(farm[k] || []).length;
  const payables = [
    ...ginBills.map((p) => ({ ...p, id: ginBillIds.get(p.id), saleId: '', storageId: '', freightOrderId: null })),
    ...(none('payables') ? (y.payables || []).filter((p) => p.payer !== 'buyer').map((p) => ({ ...p, id: newId(), saleId: '', storageId: '', freightOrderId: null })) : []),
  ];
  const inputStock = none('inputStock') ? (y.inputStock || []).map((m) => ({ ...m, id: newId() })) : [];
  const sprayJobs = none('sprayJobs') ? (y.sprayJobs || []).map((j) => ({
    ...j, id: newId(),
    paddocks: (j.paddocks || []).map((p) => ({ ...p, id: outside(p.id) })).filter((p) => p.id),
  })).filter((j) => j.paddocks.length) : [];
  return { commodities, fields, strawBaled, storages, sales, movements, invoices, payables, inputStock, sprayJobs };
}
